import asyncio,base64
from playwright.async_api import async_playwright
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(args=['--use-fake-device-for-media-stream','--use-fake-ui-for-media-stream','--autoplay-policy=no-user-gesture-required'])
        c=await b.new_context(viewport={'width':390,'height':844},permissions=['camera','microphone'])
        pg=await c.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e))); pg.on('console',lambda m: errs.append(m.text) if m.type=='error' else None)
        await pg.goto('http://localhost:8799/test.html'); await pg.evaluate("localStorage.setItem('chartready',JSON.stringify({fmMode:'one',bpm:140,fmMic:true}))"); await pg.reload(); await pg.wait_for_timeout(700)
        await pg.click('#filmBtn'); await pg.wait_for_timeout(1500); await pg.screenshot(path='s1.png')
        await pg.click('[data-fs=lay]'); await pg.wait_for_timeout(300); await pg.screenshot(path='s2.png'); await pg.click('#fsPopB [data-v=half]'); await pg.wait_for_timeout(600)
        await pg.click('[data-fs=bars]'); await pg.click('#fsPopB [data-d="-1"]'); await pg.click('#fsPopX')
        await pg.click('#fsGo'); await pg.wait_for_timeout(500); await pg.screenshot(path='s3.png')
        await pg.click('#syStart'); await pg.wait_for_timeout(2500); await pg.screenshot(path='s4.png'); await pg.wait_for_timeout(3500); await pg.screenshot(path='s5.png')
        print('sync text', await pg.evaluate("document.getElementById('syHead').textContent+' | '+document.getElementById('syMsg').textContent+' | '+document.getElementById('syNum').textContent"))
        await pg.evaluate("__nb.S.hpLag=0.08;__nb.S.hpMeas=0.08")
        await pg.click('#syGo'); await pg.wait_for_timeout(600)
        if await pg.evaluate("!document.getElementById('fSyncScr').hidden"): await pg.click('#syX'); await pg.click('#fsGo'); await pg.wait_for_timeout(600)
        await pg.wait_for_timeout(1500); await pg.screenshot(path='s6.png')
        print('bars in film', await pg.evaluate("__nb.S.bars"), 'half class', await pg.evaluate("document.getElementById('fFrame').classList.contains('half')"))
        await pg.click('#fGo'); await pg.wait_for_timeout(4000); await pg.screenshot(path='s7.png'); await pg.wait_for_timeout(8000)
        print('editor', not await pg.evaluate("document.getElementById('fEd').hidden"))
        await pg.click('[data-tool=sync]'); await pg.wait_for_timeout(300); await pg.screenshot(path='s8.png')
        await pg.click('#edSave'); await pg.wait_for_timeout(14000)
        data=await pg.evaluate("(async()=>{const b=__nb.FILM.blob; if(!b) return ''; const a=new Uint8Array(await b.arrayBuffer()); let s=''; for(let i=0;i<a.length;i++) s+=String.fromCharCode(a[i]); return btoa(s)})()")
        if data: open('/tmp/claude-0/build/out_fs.webm','wb').write(base64.b64decode(data))
        await pg.evaluate("__nb.filmExit()")
        print('bars after', await pg.evaluate("__nb.S.bars"))
        print('ERR',errs); await b.close()
asyncio.run(main())
